using UnityEngine;

// Add contact shadows (dark ovals) under all objects with Shadow2DTarget
var targets = Object.FindObjectsOfType<Shadow2DTarget>();
Sprite contactShadow = null;

// Find ShadowCircle sprite
foreach (var s in Resources.FindObjectsOfTypeAll<Sprite>())
{
    if (s.name == "ShadowCircle") { contactShadow = s; break; }
}

if (contactShadow == null) { Debug.Log("No ShadowCircle sprite found"); return; }

// Find the ProjectedShadow material to reuse its shader (or create a simple dark material)
var shadowShader = Shader.Find("Universal Render Pipeline/2D/Sprite-Lit-Default");
if (shadowShader == null) shadowShader = Shader.Find("Sprites/Default");

int added = 0;
foreach (var target in targets)
{
    var go = target.gameObject;
    // Skip if already has a contact shadow child
    if (go.transform.Find("_contactShadow") != null) continue;

    var shadowObj = new GameObject("_contactShadow");
    shadowObj.transform.SetParent(go.transform, false);

    // Position at the base of the object (local Y offset)
    var sr = go.GetComponentInChildren<SpriteRenderer>();
    float yOffset = 0f;
    if (sr != null && sr.sprite != null)
    {
        // Place at the bottom of the sprite bounds
        var bounds = sr.bounds;
        yOffset = -(bounds.extents.y * 0.7f); // Slightly above the very bottom
    }
    shadowObj.transform.localPosition = new Vector3(0f, yOffset, 0.01f);

    var shadowSr = shadowObj.AddComponent<SpriteRenderer>();
    shadowSr.sprite = contactShadow;
    shadowSr.sortingLayerName = sr != null ? sr.sortingLayerName : "Default";
    shadowSr.sortingOrder = sr != null ? sr.sortingOrder - 1 : -10;
    shadowSr.color = new Color(0f, 0f, 0f, 0.4f); // Dark semi-transparent

    // Scale based on object size
    if (sr != null && sr.sprite != null)
    {
        float objWidth = sr.sprite.bounds.size.x;
        float scaleX = Mathf.Max(objWidth * 1.2f, 0.5f);
        float scaleY = scaleX * 0.4f; // Oval shape
        shadowObj.transform.localScale = new Vector3(scaleX, scaleY, 1f);
    }

    added++;
}
Debug.Log($"Added {added} contact shadows");

